package com.recolorhphud;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.ui.ColorScheme;

@ConfigGroup("recolorhphud")
public interface RecolorHpHudConfig extends Config
{
	@ConfigItem(
		keyName = "nameColor",
		name = "Name Color",
		description = "",
		position = 0
	)
	default Color nameColor()
	{
		return ColorScheme.BRAND_ORANGE;
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "nameOpacity",
		name = " - Opacity",
		description = "0 = fully transparent, 255 = fully opaque",
		position = 1
	)
	default int nameOpacity()
	{
		return 255;
	}

	@ConfigItem(
		keyName = "nameShadowed",
		name = " - Shadow",
		description = "",
		position = 2
	)
	default boolean nameShadowed()
	{
		return true;
	}

	@ConfigItem(
		keyName = "valueColor",
		name = "Value Color",
		description = "",
		position = 3
	)
	default Color valueColor()
	{
		return Color.YELLOW;
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "valueOpacity",
		name = " - Opacity",
		description = "0 = fully transparent, 255 = fully opaque",
		position = 4
	)
	default int valueOpacity()
	{
		return 255;
	}

	@ConfigItem(
		keyName = "valueShadowed",
		name = " - Shadow",
		description = "",
		position = 5
	)
	default boolean valueShadowed()
	{
		return true;
	}

	@ConfigItem(
		keyName = "barForegroundColor",
		name = "Bar Foreground Color",
		description = "",
		position = 6
	)
	default Color barForegroundColor()
	{
		return new Color(0, 170, 0);
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "barForegroundOpacity",
		name = " - Opacity",
		description = "0 = fully transparent, 255 = fully opaque",
		position = 7
	)
	default int barForegroundOpacity()
	{
		return 255;
	}

	@ConfigItem(
		keyName = "barBackgroundColor",
		name = "Bar Background Color",
		description = "",
		position = 8
	)
	default Color barBackgroundColor()
	{
		return new Color(170, 0, 0);
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "barBackgroundOpacity",
		name = " - Opacity",
		description = "0 = fully transparent, 255 = fully opaque",
		position = 9
	)
	default int barBackgroundOpacity()
	{
		return 255;
	}

	@ConfigItem(
		keyName = "barProgressColor",
		name = "Bar Sliding Color",
		description = "",
		position = 10
	)
	default Color barProgressColor()
	{
		return ColorScheme.PROGRESS_INPROGRESS_COLOR;
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "barProgressOpacity",
		name = " - Opacity",
		description = "0 = fully transparent, 255 = fully opaque",
		position = 11
	)
	default int barProgressOpacity()
	{
		return 255;
	}

	@Range(min = 0, max = 255)
	@ConfigItem(
		keyName = "frameOpacity",
		name = "Frame Opacity",
		description = "0 = fully transparent, 255 = fully opaque",
		position = 12
	)
	default int frameOpacity()
	{
		return 255;
	}
}

package com.recolorhphud;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Recolor HP Hud"
)
public class RecolorHpHudPlugin extends Plugin
{
	public static final int HP_HUD_GREEN = 51200;
	public static final int HP_HUD_RED = 13107200;
	public static final int HP_HUD_DARK_GREEN = 36864;

	@Inject
	private Client client;

	@Inject
	private RecolorHpHudConfig config;

	private int originalBarForeground = 0;
	private int originalBarBackground = 0;
	private int originalBarProgress = 0;

	@Subscribe
	public void onBeforeRender(BeforeRender beforeRender)
	{
		Widget border = client.getWidget(InterfaceID.HpbarHud.OUTER_BORDER);
		if (border != null)
		{
			border.setOpacity(255 - config.frameOpacity());
		}

		Widget frame = client.getWidget(InterfaceID.HpbarHud.NAME_BACKING);
		if (frame != null)
		{
			frame.setOpacity(255 - config.frameOpacity());
		}

		Widget name = client.getWidget(InterfaceID.HpbarHud.CREATURE_NAME);
		if (name != null)
		{
			name.setTextColor(config.nameColor().getRGB());
			name.setOpacity(255 - config.nameOpacity());
			name.setTextShadowed(config.nameShadowed());
		}

		Widget value = client.getWidget(InterfaceID.HpbarHud.HP_BAR_TEXT);
		if (value != null)
		{
			value.setTextColor(config.valueColor().getRGB());
			value.setOpacity(255 - config.valueOpacity());
			value.setTextShadowed(config.valueShadowed());
		}

		Widget barForeground = client.getWidget(InterfaceID.HpbarHud.HEALTH_BAR_REMAINING);
		if (barForeground != null)
		{
			if (originalBarForeground == HP_HUD_GREEN)
			{
				barForeground.setTextColor(config.barForegroundColor().getRGB());
			}
			barForeground.setOpacity(255 - config.barForegroundOpacity());
		}

		Widget barBackground = client.getWidget(InterfaceID.HpbarHud.HEALTH_BAR_BACK);
		if (barBackground != null)
		{
			if (originalBarBackground == HP_HUD_RED)
			{
				barBackground.setTextColor(config.barBackgroundColor().getRGB());
			}
			barBackground.setOpacity(255 - config.barBackgroundOpacity());
		}

		Widget barProgress = client.getWidget(InterfaceID.HpbarHud.HEALTH_BAR_SLIDING);
		if (barProgress != null)
		{
			if (originalBarProgress == HP_HUD_DARK_GREEN)
			{
				barProgress.setTextColor(config.barProgressColor().getRGB());
			}
			barProgress.setOpacity(255 - config.barProgressOpacity());
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired scriptPreFired)
	{
		if (scriptPreFired.getScriptId() != ScriptID.HP_HUD_UPDATE)
		{
			return;
		}

		Widget barForeground = client.getWidget(InterfaceID.HpbarHud.HEALTH_BAR_REMAINING);
		if (barForeground != null)
		{
			originalBarForeground = barForeground.getTextColor();
		}

		Widget barBackground = client.getWidget(InterfaceID.HpbarHud.HEALTH_BAR_BACK);
		if (barBackground != null)
		{
			originalBarBackground = barBackground.getTextColor();
		}

		Widget barProgress = client.getWidget(InterfaceID.HpbarHud.HEALTH_BAR_SLIDING);
		if (barProgress != null)
		{
			originalBarProgress = barProgress.getTextColor();
		}
	}

	@Provides
	RecolorHpHudConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RecolorHpHudConfig.class);
	}
}

package com.recolorhphud;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RecolorHpHudPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RecolorHpHudPlugin.class);
		RuneLite.main(args);
	}
}
